import sys
import subprocess
import re
from collections import defaultdict

def parse_vars_file(vars_file):
    vars_dict = defaultdict(str)
    with open(vars_file, 'r', encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith('#'):
                continue
            parts = line.split('=', 1)
            if len(parts) != 2:
                continue
            name, value = parts
            vars_dict[name] = value
    return vars_dict

def evaluate_expression(expr, vars_dict):
    try:
        # Replace identifiers with their values
        for name, value in vars_dict.items():
            if re.fullmatch(r'^[a-zA-Z0-9_]+$', name):
                expr = expr.replace(name, f'"{value}"')

        # Evaluate the expression safely
        try:
            result = eval(expr, {'__builtins__': None}, {})
            if isinstance(result, str):
                raise ValueError("Expression result is a string")
            return result
        except (NameError, SyntaxError, ValueError) as e:
            raise ValueError(f"Invalid expression: {expr}") from e
    except Exception as e:
        raise ValueError(f"Error evaluating expression: {expr}") from e

def expand_template(template_file, vars_dict):
