                if value.isdigit():
                    return value
                return value
            else:
                sys.stderr.write(f"Unresolved placeholder: {placeholder}\n")
                sys.exit(1)
        return placeholder

    pattern = re.compile(r'{{(.*?)}}')
    expanded = pattern.sub(replace_placeholder, content)
    return expanded

