#!/usr/bin/env python3
import sys
import re
import subprocess
import os

def parse_vars_file(vars_file):
    vars_dict = {}
    with open(vars_file, 'r', encoding='utf-8') as f:
        for line in f:
            stripped = line.strip()
            if not stripped or stripped.startswith('#'):
                continue
            parts = re.split(r'=+', stripped, maxsplit=1)
            if len(parts) < 2:
                continue
            name = parts[0].strip()
            value = parts[1].strip()
            vars_dict[name] = value
    return vars_dict

def expand_expression(expr, vars_dict):
    try:
        # Replace identifiers with their values
        for name in vars_dict:
            if name in expr:
                expr = expr.replace(name, str(vars_dict[name]))
        # Evaluate the expression
        return eval(expr)
    except:
        return None

def expand_template(template_file, vars_dict):
    with open(template_file, 'r', encoding='utf-8') as f:
        content = f.read()
    output = []
    i = 0
    n = len(content)
    while i < n:
        if content.startswith('{{', i):
            j = content.find('}}', i)
            if j == -1:
                raise ValueError(f"Unclosed placeholder at position {i}")
            placeholder = content[i:j+2]
            if placeholder == '{{}}':
                output.append('')
                i = j + 2
                continue
            if placeholder.startswith('{{= '):
                expr = placeholder[4:-2]
                try:
                    value = expand_expression(expr, vars_dict)
                    if value is None:
                        raise ValueError(f"Invalid expression: {expr}")
                    output.append(str(value))
                except Exception as e:
                    print(f"Error evaluating expression: {placeholder}", file=sys.stderr)
                    sys.exit(1)
                i = j + 2
            elif placeholder.startswith('{{$ '):
                cmd = placeholder[4:-2]
                try:
                    result = subprocess.run(cmd, shell=True, check=True, text=True, capture_output=True)
                    output.append(result.stdout.rstrip('\n'))
                except subprocess.CalledProcessError as e:
                    print(f"Command failed: {placeholder}", file=sys.stderr)
                    sys.exit(2)
                except Exception as e:
                    print(f"Error executing command: {placeholder}", file=sys.stderr)
                    sys.exit(2)
                i = j + 2
            else:
                print(f"Unsupported placeholder: {placeholder}", file=sys.stderr)
                sys.exit(1)
        else:
            output.append(content[i])
            i += 1
    return ''.join(output)

def main():
    if len(sys.argv) != 3:
        print("Usage: python expand.py TEMPLATE_FILE VARS_FILE", file=sys.stderr)
        sys.exit(1)
    template_file = sys.argv[1]
    vars_file = sys.argv[2]
    try:
        vars_dict = parse_vars_file(vars_file)
        expanded = expand_template(template_file, vars_dict)
        print(expanded, end='')
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == '__main__':
    main()

